action.script:

import com.liferay.commerce.constants.CommerceOrderConstants;
import com.liferay.commerce.model.CommerceOrder;
import com.liferay.commerce.model.CommerceOrderItem;
import com.liferay.commerce.product.model.CPInstance;
import com.liferay.commerce.product.model.CPSubscriptionInfo;
import com.liferay.commerce.product.service.CPInstanceLocalServiceUtil;
import com.liferay.commerce.service.CommerceOrderLocalServiceUtil;
import com.liferay.object.service.ObjectEntryLocalServiceUtil;
import com.liferay.portal.kernel.util.GetterUtil;
import com.liferay.portal.kernel.workflow.WorkflowConstants;
import com.liferay.portal.kernel.workflow.WorkflowStatusManagerUtil;

import java.math.BigDecimal;

Map<String, Serializable> objectEntryValuesMap = ObjectEntryLocalServiceUtil.getValues(kaleoInstanceToken.getClassPK());

int billingOption = GetterUtil.getInteger(objectEntryValuesMap.get("billingOption"));

BigDecimal finalPrice = 0.0;

Map<String, Serializable> quoteComparisonEntryValuesMap = ObjectEntryLocalServiceUtil.getValues(GetterUtil.getLong(objectEntryValuesMap.get("r_quoteComparisonToRaylifeOrders_c_quoteComparisonId")));

CommerceOrder commerceOrder = CommerceOrderLocalServiceUtil.getCommerceOrder(GetterUtil.getLong(objectEntryValuesMap.get("r_commerceOrderToRaylifeOrders_commerceOrderId")));

List<CommerceOrderItem> commerceOrderItems = commerceOrder.getCommerceOrderItems();

CommerceOrderItem commerceOrderItem = commerceOrderItems.get(0);

CPInstance cpInstance = commerceOrderItem.fetchCPInstance();

if (billingOption == 1) {
	finalPrice = GetterUtil.getNumber(quoteComparisonEntryValuesMap.get("promo"));
}
else {
	finalPrice = GetterUtil.getNumber(quoteComparisonEntryValuesMap.get("price")) / cpInstance.getSubscriptionLength();
}

commerceOrder.setSubtotal(finalPrice);
commerceOrder.setTotal(finalPrice);

CommerceOrderLocalServiceUtil.updateCommerceOrder(commerceOrder);

WorkflowStatusManagerUtil.updateStatus(WorkflowConstants.getLabelStatus("approved"), workflowContext);
